const fields = $json.fields || $json;
const recordId = $json.id || fields.record_id || '';

function safeLower(v) {
  return (v ?? '').toString().trim().toLowerCase();
}

function parseBool(v) {
  if (v === true || v === false) return v;
  const s = safeLower(v);
  return s === 'true' || s === '1' || s === 'yes';
}

function parseDateTime(dateStr, timeStr) {
  if (!dateStr) return null;
  const dt = new Date(`${dateStr}T${timeStr || '09:00'}:00`);
  return isNaN(dt.getTime()) ? null : dt;
}

function formatPhone(phone) {
  const phoneStr = (phone || '').toString().replace(/[^0-9]/g, '');
  return phoneStr ? '+' + phoneStr : '';
}

const now = new Date();

const apptDate = fields.appointment_date || fields.AppointmentDate || fields.date || '';
const apptTime = fields.appointment_time || fields.AppointmentTime || fields.time || '';
const appointmentAt = parseDateTime(apptDate, apptTime);
const diffHours = appointmentAt ? (appointmentAt.getTime() - now.getTime()) / 3600000 : null;

const status = safeLower(fields.status || fields.Status);
const preferredChannel = safeLower(fields.preferred_channel || fields.PreferredChannel || 'sms');

const reminder24Sent = parseBool(fields.reminder_24h_sent ?? fields.Reminder24hSent);
const followupSent = parseBool(fields.followup_sent ?? fields.FollowupSent);
const consent = parseBool(fields.consent ?? fields.Consent);

let workflowType = 'ignore';

if (
  status === 'scheduled' &&
  diffHours !== null &&
  diffHours > 0 &&
  diffHours <= 24 &&
  !reminder24Sent
) {
  workflowType = 'reminder';
} else if (status === 'completed' && !followupSent) {
  workflowType = 'completed_followup';
} else if ((status === 'no_show' || status === 'noshow') && !followupSent) {
  workflowType = 'no_show_followup';
}

const patientName = fields.patient_name || fields.PatientName || '';
const firstName =
  fields.first_name ||
  fields.FirstName ||
  (patientName ? patientName.split(' ')[0] : '') ||
  'there';

return {
  json: {
    recordId,
    patientId: fields.patient_id || fields.PatientID || '',
    appointmentId: fields.appointment_id || fields.AppointmentID || '',
    patientName,
    firstName,
    phone: formatPhone(fields.phone || fields.Phone),
     telegram_chat_id: fields.telegram_chat_id || fields.Telegram_Chat_Id || '',
    email: fields.email || fields.Email || '',
    consent,
    preferredChannel,
    appointmentDate: apptDate,
    appointmentTime: apptTime,
    appointmentAt: appointmentAt ? appointmentAt.toISOString() : '',
    diffHours,
    providerName: fields.provider_name || fields.ProviderName || '',
    specialty: fields.specialty || fields.Specialty || '',
    clinicName: fields.clinic_name || fields.ClinicName || '',
    clinicAddress: fields.clinic_address || fields.ClinicAddress || '',
    status,
    reminder24Sent,
    followupSent,
    workflowType
  }
};
